---@class UISkillCompoundDialog
---@field skills                        	SuperScrollView.LoopGridView            
---@field Root                          	UnityEngine.RectTransform               
local UISkillCompoundDialog = Class("UISkillCompoundDialog")

function UISkillCompoundDialog:__init() 
    self._allSkillCompund = {}      --所有的合卡数据
    self._curSelectInd = -1         --当前选择的下标
    self._curUseId = nil            --当前使用的合卡id
    self._collectData = {}          --收藏的信息

    self._curQuestId = nil        --当前关卡id
    self._curTeamIndex = nil      --当前队伍下标
end

function UISkillCompoundDialog:__delete()
    self._allSkillCompund = {}     --所有的合卡数据
    self._curUseId = nil        --当前选择的合卡类型
    self._curQuestId = nil        --当前关卡id
    self._curTeamIndex = nil      --当前队伍下标
end

function UISkillCompoundDialog:Awake()
    SetButtonAction(self.ButtonClose, function()
        UIModule.CloseDialog(self.controller)
    end)

    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnChooseSkill))
    SetButtonAction(self.BtnTopping, Bind(self, self.OnBtnCollection))
    SetButtonAction(self.BtnSupply, Bind(self, self.OnReplenishEnergy))
end

--初始化
function UISkillCompoundDialog:InitData()
    --收藏的数据
    self._collectData = {} 
    local t = CfUtils.GetLocalData("SKILLCompound")
    if checkString(t) == "" then
    else
        self._collectData = checkTable(table.deserialize(t))
    end

    self._allSkillCompund = self:GetAllSkillCompund()
end


function UISkillCompoundDialog:FillSelf()
    if not self._isInitView then
        self._isInitView = true
        self.LoopList:InitListView(table.count(self._allSkillCompund), Bind(self, self.OnRefreshIndex))
    else
        GameUtils.ReloadData(self.LoopList, #self._allSkillCompund)
    end

    self:FillSkillInfo()
end

function UISkillCompoundDialog:OnRefreshIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("SkillCell")
    local data = self._allSkillCompund[index + 1]

    local scr = CfUtils.GetLuaScr(cell, UISkillCompoundNode)
    if scr then
        scr:Refresh(data, function()
            if index + 1 == checkNumber(self._curSelectInd) then 
                return
            end

            self:ChooseSkill(index)
        end, self._curQuestId, self._curTeamIndex)

        scr:RefreshCollectActive(self:IsCollect(data.id))

        if self._curSelectInd == index + 1 then
            scr:RefreshSelectActive(true)
        end
    end
    return cell
end

--选择队列
function UISkillCompoundDialog:ChooseSkill(index)
    local go
    local lastSelectInd = self._curSelectInd
    if checkNumber(lastSelectInd) > 0 then
        go = self.LoopList:GetShownItemByItemIndex(lastSelectInd - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UISkillCompoundNode)
            if lastScr then
                lastScr:RefreshSelectActive(false)
            end
        end
    end

    self._curSelectInd = index + 1
    if checkNumber(self._curSelectInd) > 0 then
        go = self.LoopList:GetShownItemByItemIndex(self._curSelectInd - 1)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UISkillCompoundNode)
            if curScr then
                curScr:RefreshSelectActive(true)
            end
        end
    end

    self:FillSkillInfo()
end

function UISkillCompoundDialog:OnBtnCollection()
    local data = self._allSkillCompund[self._curSelectInd]
    if not data then
        return
    end
    self:CollectSkillId(data.id)

    local go = self.LoopList:GetShownItemByItemIndex(self._curSelectInd - 1)
    if go then
        local curScr = CfUtils.GetLuaScr(go, UISkillCompoundNode)
        if curScr then
            curScr:RefreshCollectActive(self:IsCollect(data.id))
        end
    end
    CfUtils.SetUISwitchImage(self.BtnTopping.transform:Find("ImgTopping"), self:IsCollect(data.id) and 2 or 1)
end

function UISkillCompoundDialog:FillSkillInfo()
    local vo = self._allSkillCompund[self._curSelectInd]
    if not vo then
        CfUtils.SetActive(self.SkillDetails, false)
        return
    end
    CfUtils.SetActive(self.SkillDetails, true)
    CfUtils.SetUISwitchImage(self.BtnTopping.transform:Find("ImgTopping"), self:IsCollect(vo.id) and 2 or 1)

    local data = QuestConfMgr:GetInstance():GetMergeSkillData(vo.id)
    local catVo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(vo.catId)
    CfUtils.FillText(self.TextName, catVo.name)

    CfUtils.SetActive(self.Lock, not data)
    CfUtils.SetActive(self.Unlock, data)

    local scr = CfUtils.GetLuaScr(self.TextNumber.transform:Find("StarLevel"), "Game.MaidCoffee.MaidCoffeeUIDialog.OverseaManageCatBallStarGroup")
    --未解锁
    if not data then
        CfUtils.SetActive(self.BtnTopping, false)
        CfUtils.FillText(self.TextNumber, 1)

        local lv, star = self:GetDefaultLvStar()
        if scr then
            scr:FreshUI(star)
        end

        local skillEffectVo = MaidCoffeeUtils.GetMaidCoffeeCatRollSkillGrowVo(vo.id, star)
        if skillEffectVo then
            local effectVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(skillEffectVo.skillNumId)
            CfUtils.FillText(self.TextDesc2, effectVo.desc)
        end
        return
    end

    CfUtils.SetActive(self.BtnTopping, true)
    CfUtils.FillText(self.TextNumber, data.level)

    if scr then
        scr:FreshUI(data.star)
    end

    local skillEffectVo = MaidCoffeeUtils.GetMaidCoffeeCatRollSkillGrowVo(vo.id, data.star)
    if skillEffectVo then
        local effectVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(skillEffectVo.skillNumId)
        CfUtils.FillText(self.TextDesc2, effectVo.desc)
    end

    local curNum = checkNumber(data.cafeEnergy)
    local maxNum = MaidCoffeeUtils.CalcCatRollEnergyLimit(vo.catId, data.level)
    self.Slider.value = curNum/maxNum

    local isEnough = curNum >= maxNum
    CfUtils.SetUISwitchImage(self.BtnSupply.transform:Find("ImgBg"), isEnough and 1 or 2)
    CfUtils.SetActive(self.CommonBtnConsumePop, not isEnough)

    if not isEnough then
        local parVo1 = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(13)
        local parVo2 = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(14)

        local constNum = (maxNum - curNum) * checkNumber(parVo2.num)
        CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, parVo1.num, constNum)
    end
    CfUtils.FillText(self.TextNumber2, curNum.."/"..maxNum)

    CfUtils.SetActive(self.StatusEquiped, checkNumber(self._curUseId) == checkNumber(vo.id))
    CfUtils.SetActive(self.FontStyleButton, checkNumber(self._curUseId) ~= checkNumber(vo.id))

    local vo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(20)
    CfUtils.FillText(self.TextNumber3, vo.num)
end

function UISkillCompoundDialog:GetDefaultLvStar()
    local t = CfUtils.GetCf(AutoIds.IdSetting4002, "MaidCoffeeCatRollStarVo", true)
    local star = t[1].starId
    local t = CfUtils.GetCf(AutoIds.IdSetting4001, "MaidCoffeeCatRollLevelVo", true)
    local lv = t[1].rankId
    return lv, star
end

--恢复能量
function UISkillCompoundDialog:OnReplenishEnergy()
    local vo = self._allSkillCompund[self._curSelectInd]
    local data = QuestConfMgr:GetInstance():GetMergeSkillData(vo.id)
    if not data then
        GameUtils.Toast(localize("该技能未解锁"))
        return
    end
    local curNum = checkNumber(data.cafeEnergy)
    local maxNum = MaidCoffeeUtils.CalcCatRollEnergyLimit(vo.catId, data.level)
    if curNum >= maxNum then
        GameUtils.Toast(localize("能量已满"))
        return
    end

    local parVo1 = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(13)
    local parVo2 = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(14)
    local constNum = (maxNum - curNum) * checkNumber(parVo2.num)
    if GoodsUtils.GetThingNo(parVo1.num) < constNum then
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(parVo1.num)
        GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
        return
    end

    GameUtils.Request(Interfaces.MaidCoffeeCatCureEnergy, {playerCatId = data.id}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            GoodsUtils.DrawRewards({{goodsId = parVo1.num, num = -constNum}})
            local jsonData = checkTable(response.data)
            local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
            eggComponent:UpdateCatEnergy(data.id, jsonData.cafeEnergy)

            self:FillSkillInfo()

            Events.Broadcast(Constants.EventNames.SkillCompoundChange, nil)
        end
    end)
end

function UISkillCompoundDialog:GetAllSkillCompund()
    local t = CfUtils.GetCf(AutoIds.IdSetting3085, "MergeSkillTypeVo", true)
    local _t = {}

    local curUseVo
    if t then
        for k, vo in pairs(t) do
            --当前的
            if checkNumber(self._curUseId) == checkNumber(vo.id) then
                curUseVo = vo
            else
                table.insert(_t, vo) 
            end
        end
    end

    for i = 1, #_t - 1 do
        for j = i + 1, #_t do
            local data1 = _t[i]
            local data2 = _t[j]

            local isUnlock1 = QuestConfMgr:GetInstance():GetMergeSkillData(data1.id)
            local isUnlock2 = QuestConfMgr:GetInstance():GetMergeSkillData(data2.id)

            local isTrue = false
            --收藏
            if self:IsCollect(data2.id) and not self:IsCollect(data1.id) then 
                isTrue = true
            elseif isUnlock2 and not isUnlock1 then
                isTrue = true
            else
                isTrue = checkNumber(data2.id) < checkNumber(data1.id)
            end

            if isTrue then 
                local bufferData = _t[i]
                _t[i] = _t[j]
                _t[j] = bufferData
            end
        end
    end

    if curUseVo then
        table.insert(_t, 1, curUseVo) 
    end
    return _t
end

--选择合卡机
function UISkillCompoundDialog:OnBtnChooseSkill()
    local data = self._allSkillCompund[self._curSelectInd]
    if not data then
        return
    end

    local catData = QuestConfMgr:GetInstance():GetMergeSkillData(data.id)
    if not catData then
        return
    end
    
    teamComponent:SetTeamMergeSkillId(catData.id, self._curQuestId, self._curTeamIndex)
    UIModule.CloseDialog(self.controller)
end

function UISkillCompoundDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local isTrue = false

        local argument = self.controller.Argument.parameters
        self._curQuestId = checkNumber(argument.levelId)  -- 关卡ID
        self._curTeamIndex = argument.teamIndex  
    
        local catId = teamComponent:GetCurSkillCompoundId(self._curQuestId, self._curTeamIndex)
        if checkNumber(catId) > 0 then
            local data = catEggComponent:GetCat(catId)
            local vo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(data.catId)
            if vo then
                self._curUseId = vo.skillId
            end
        end

        self:InitData()

        if checkNumber(self._curUseId) <= 0 then
            self._curSelectInd = 0
        else
            self._curSelectInd = self:GetInd(self._curUseId)
        end
        self._curSelectInd = 1

        print(table.dump(catEggComponent.cats))
    end))
    return coWait
end

function UISkillCompoundDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            --Events.RemoveListener(Constants.EventNames.SkillCompoundChange, self.EventSkillCompoundChange)
        end
        CfUtils.WriteLocalData("SKILLCompound", table.serialize(self._collectData))

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UISkillCompoundDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FillSelf()
    end))
    return coWait
end

--收藏一个节能
function UISkillCompoundDialog:CollectSkillId(skillId)
    if checkNumber(self._collectData[checkString(skillId)]) == 1 then
        self._collectData[checkString(skillId)] = nil
    else
        self._collectData[checkString(skillId)] = 1
    end
end

function UISkillCompoundDialog:GetInd(id)
    if checkNumber(id) == 0 then
        return 1
    end
    for k, v in pairs(self._allSkillCompund) do
        if checkNumber(id) == checkNumber(v.id) then
            return k
        end
    end
    return 1
end

function UISkillCompoundDialog:IsCollect(skillId)
    if not skillId then
        return false
    end

    for k, v in pairs(self._collectData) do
        if checkNumber(skillId) == checkNumber(k) then
            return true
        end
    end
    return false
end

return UISkillCompoundDialog
